	(1, 1, 0, 0, 0, 0, '|', 0, 0, 1, 1.00, 1, 1, 1500, 'Thôn nhỏ yên tĩnh nằm giữa đồi núi và đồng bằng phía tây đại lục, tương truyền là nơi khởi nguồn văn minh Đại Lục Vô Ưu.', 1, 1263283132508, 1, -1, 0, 1, 'Xuất Vân Thôn', -1, '310,1370|290,1020|470,830|450,660|690,500|970,400|1060,250|1390,400|1610,570|1320,750|1290,1220|1880,1310|800,1170|580,1000|710,800|700,610|1030,480|1200,620|940,720|920,910', '310,1370|290,1020|470,830|450,660|690,500|970,400|1060,250|1390,400|1610,570|1320,750|1290,1220|1880,1310|800,1170|580,1000|710,800|700,610|1030,480|1200,620|940,720|920,910', 1015015000001, '0', 1, 1, 1000, 1000, 1, 2, 2000),
	(2, -1, 50, 10, 1, 0, '|107|154|1|3|202|15|17|16|18|', 0, 0, 1, 1.00, 1, 1, 1600, 'Vùng ngoại ô Xuất Vân dẫn đến Đông Huyền, là nơi săn bắn và luyện tập thích hợp cho cấp 6 - 10.', 1, 1255926624051, 5, -1, 1, 1, 'Đông Xuất Vân', -1, '790,270|450,950|670,1360|710,880|1750,970|1180,740|2190,1260|330,1170|1830,910|2190,620|2150,360|1740,300|1330,300|1050,360|630,1450|1940,1400|600,840', '790,270|450,950|670,1360|710,880|1750,970|1180,740|2190,1260|330,1170|1830,910|2190,620|2150,360|1740,300|1330,300|1050,360|630,1450|1940,1400|600,840', 1015015000002, '0', 1, 0, 2000, 900, 1, 2, 2400),
	(3, 1, 50, 10, 1, 0, '|14|4|56|2|181|15|17|16|18|', 0, 0, 1, 1.00, 1, 1, 1800, 'Nơi bắt đầu học tập, nhận sự trợ giúp từ tự nhiên. Thích hợp cho cấp độ từ 1 - 5.', 1, 1256546454505, 2, -1, 1, 1, 'Vân Đài', -1, '1720,310|2060,780|1870,1090|1690,1460|1310,1510|510,1300|520,960|930,780|800,430|1090,1110|1480,860|1620,550|1860,360|2110,280|660,350|560,600|830,920|1160,960', '1720,310|2060,780|1870,1090|1690,1460|1310,1510|510,1300|520,960|930,780|800,430|1090,1110|1480,860|1620,550|1860,360|2110,280|660,350|560,600|830,920|1160,960', 1015015000003, '0', 1, 0, 1000, 1000, 1, 2, 2500),
	(4, 1, 50, 10, 1, 0, '|114|42|108|109|203|15|17|16|18|', 0, 0, 1, 1.00, 1, 1, 2000, 'Vùng đất sơ khai, nơi có kiến thức nghìn năm lưu truyền lại. Thích hợp cho cấp độ từ 11 - 15.', 1, 1271688609673, 8, -1, 3, 1, 'Thiện Tĩnh Địa', -1, '661,517|1091,493|1100,750|1587,758|1544,973|1168,1094|608,1413|871,1696|511,1548|2629,1218|800,1720|780,1180|1610,930|980,620|400,680|1480,340|2670,330|2760,910|2530,1280|2250,1750', '661,517|1091,493|1100,750|1587,758|1544,973|1168,1094|608,1413|871,1696|511,1548|2629,1218|800,1720|780,1180|1610,930|980,620|400,680|1480,340|2670,330|2760,910|2530,1280|2250,1750', 1015015000004, '0', 1, 0, 1500, 800, 1, 2, 3000),
	(5, 1, 50, 10, 1, 0, '|138|136|135|134|197|17|15|16|18|', 0, 0, 1, 1.00, 1, 1, 1700, 'Thôn nhỏ ven hồ Lê Dương có phong cảnh hữu tình mê hoặc người lữ khách. Thích hợp cho cấp độ từ 51 - 55.', 1, 1256547023812, 30, -1, 1, 1, 'Lê Dương Thôn', 1, '677,584|583,816|298,1048|473,1360|791,1288|433,1426|1388,1326|1248,1152|277,1110|680,570|1030,820|1720,830|790,1290|140,1280|1640,1420|1090,1410|440,520|1800,750|1690,1550|1140,1220|860,1450|140,1360|390,1570|670,870|1120,1470', '677,584|583,816|298,1048|473,1360|791,1288|433,1426|1388,1326|1248,1152|277,1110|680,570|1030,820|1720,830|790,1290|140,1280|1640,1420|1090,1410|440,520|1800,750|1690,1550|1140,1220|860,1450|140,1360|390,1570|670,870|1120,1470', 1015015000005, '0', 9, 0, 885, 753, 1, 2, 2000),
	(6, 1, 50, 10, 1, 0, '|13|148|103|149|201|15|16|18|', 0, 0, 1, 1.00, 1, 1, 1800, 'Vùng đất nguy hiểm nhất của Lê Dương, rất ít người qua lại. Thích hợp cho cấp độ từ 61 - 65.', 1, 1256368398362, 40, -1, 0, 1, 'Lê Dương Nam', 1, '871,271|786,479|875,647|804,1454|1846,1346|1740,901|2124,481|1622,281|1650,790|1118,1076|730,1630|1450,1220|720,1100|420,720|2300,1240|1440,1660|2400,290|540,630|880,1110|520,1580|1720,1680|2230,1580|1580,780', '871,271|786,479|875,647|804,1454|1846,1346|1740,901|2124,481|1622,281|1650,790|1118,1076|730,1630|1450,1220|720,1100|420,720|2300,1240|1440,1660|2400,290|540,630|880,1110|520,1580|1720,1680|2230,1580|1580,780', 1015015000006, '0', 9, 0, 1800, 800, 1, 2, 2500),
	(7, 1, 50, 10, 1, 0, '|', 0, 0, 1, 1.00, 1, 1, 1700, 'Nơi ở của thánh hiền quân tử, giúp rèn luyện tính khiêm tốn học hỏi, kiên cường bất khuất. Thích hợp cho cấp độ từ 81- 85.', 1, 1256547892786, 75, -1, 1, 1, 'Quân Cổ Đạo', 1, '520,840|1460,770|1160,1590|2050,1440|2020,670|200,280|1200,320|80,860|170,1460|1010,1650|1280,1100|1830,1290|2100,860|2130,390|1700,320', '520,840|1460,770|1160,1590|2050,1440|2020,670|200,280|1200,320|80,860|170,1460|1010,1650|1280,1100|1830,1290|2100,860|2130,390|1700,320', 1015015000007, '0', 9, 0, 721, 486, 1, 2, 2200),
	(8, 1, 50, 10, 1, 0, '|133|132|65|129|196|17|15|16|18|', 0, 0, 1, 1.00, 1, 1, 2000, 'Rừng cây rộng lớn nằm giữa Lê Dương và Hư Không Mạc, là nơi ở của bầy sói. Thích hợp cho cấp độ từ 46 - 50.', 1, 1256368749063, 30, -1, 3, 1, 'Tháp Khắc Nguyên', 1, '465,480|720,687|1760,559|2073,606|1595,875|2073,1079|2473,1089|1976,1206|609,1027|966,1002|1840,1830|2700,1220|1850,900|2330,570|1410,610|650,290|720,1400|770,1910|190,1880|1370,550|70,520|100,1450|850,1920|1160,1180|1860,1890|2650,1190|2550,660|1870,920', '465,480|720,687|1760,559|2073,606|1595,875|2073,1079|2473,1089|1976,1206|609,1027|966,1002|1840,1830|2700,1220|1850,900|2330,570|1410,610|650,290|720,1400|770,1910|190,1880|1370,550|70,520|100,1450|850,1920|1160,1180|1860,1890|2650,1190|2550,660|1870,920', 1015015000008, '0', 9, 0, 850, 900, 1, 2, 3000),
