	(11, 1, 0, 0, 0, 0, '|', 0, 0, 1, 1.00, 1, 1, 1500, 'Tộc Linh Vũ nằm ở phía nam đại lục, là nơi đào tạo ra những danh y tài ba và thông hiểu lễ nghĩa.', 1, 1256291733654, 10, -1, 2, 1, 'Linh Vũ Tộc', -1, '1450,1380|1030,970|1620,960|880,290|600,650|495,523|1176,987|745,1019|785,450|1771,1002|300,910|1473,1362|1336,681|814,744|754,1264|293,1317', '1450,1380|1030,970|1620,960|880,290|600,650|495,523|1176,987|745,1019|785,450|1771,1002|300,910|1473,1362|1336,681|814,744|754,1264|293,1317', 1015015000011, '0', 11, 1, 1000, 1000, 1, 2, 2100),
	(2002, 1, 50, 10, 1, 0, NULL, 0, 0, 1, 1.00, -1, 1, 2400, NULL, 1, 1242019954656, 1, -1, 5, 1, 'Tầng 2 Mê Huyễn Động', -1, NULL, NULL, 1015015140002, NULL, 9, 0, 2120, 360, -1, 2, 3200),
