	(13, 1, 0, 0, 0, 0, '|', 0, 0, 1, 1.00, 1, 1, 1500, 'Nằm trên đỉnh núi tuyết phía tây, là cái nôi ươm tạo nghệ thuật gia âm nhạc.', 1, 1238503451609, 10, -1, 2, 1, 'Liêu Vân Tộc', -1, '1590,1270|1710,410|1250,460|640,1360|140,1030|730,600|552,1049|350,1435|907,1314|1990,741|874,623|1580,1368|796,938|1091,1158|1736,456|1292,771', '1590,1270|1710,410|1250,460|640,1360|140,1030|730,600|552,1049|350,1435|907,1314|1990,741|874,623|1580,1368|796,938|1091,1158|1736,456|1292,771', 1015015000013, '0', 13, 1, 1000, 1000, 1, 2, 2100),
	(14, 1, 50, 10, 1, 0, '|79|146|147|74|198|15|16|17|18|', 0, 0, 1, 1.00, 1, 1, 2624, 'Nơi có nhiều vật quý, nhưng là vùng đất chết, vô số sinh linh đã bị chôn vùi. Thích hợp cho cấp độ từ 56 - 60.', 1, 1249553052995, 30, -1, 3, 1, 'Hư Không Mạc', 1, '430,490|870,740|1450,1050|240,1040|350,2260|1170,2390|2550,2330|3340,1990|3730,1500|3690,660|2550,860|1900,1150|1260,1920|2510,1720|420,360|170,1080|190,1930|860,2390|1980,2400|3290,2030|3770,1070|3730,550|2000,1140|1520,800', '430,490|870,740|1450,1050|240,1040|350,2260|1170,2390|2550,2330|3340,1990|3730,1500|3690,660|2550,860|1900,1150|1260,1920|2510,1720|420,360|170,1080|190,1930|860,2390|1980,2400|3290,2030|3770,1070|3730,550|2000,1140|1520,800', 1015015000014, '0', 9, 0, 2057, 1309, 1, 2, 4070),
	(15, 1, 50, 10, 1, 0, '|73|115|7|54|184|15|17|16|18|', 0, 0, 1, 1.00, 1, 1, 2000, 'Phía bắc hồ Lê Dương là nguồn nước của Đông Huyền, tuy phong cảnh hữu tình nhưng khá nguy hiểm. Thích hợp cho cấp độ từ 16 - 20', 1, 1256542757200, 10, -1, 3, 1, 'Lê Dương Bắc', -1, '900,600|1240,260|1430,600|1580,680|2070,580|2170,350|2650,440|2800,750|2790,1180|2420,1600|2770,1790|2150,1660|1760,1750|1340,1690|880,1480|460,1490|810,1230|830,1000|420,880', '900,600|1240,260|1430,600|1580,680|2070,580|2170,350|2650,440|2800,750|2790,1180|2420,1600|2770,1790|2150,1660|1760,1750|1340,1690|880,1480|460,1490|810,1230|830,1000|420,880', 1015015000015, '0', 9, 0, 1126, 760, 1, 2, 3000),
	(16, 1, 50, 10, 1, 0, '|285|286|287|297|', 0, 0, 1, 1.00, 1, 1, 1600, 'Chim hót véo von, bướm ong bay lượn, trăm hoa đua nở, tựa chốn thiên đường. Thích hợp cho cấp độ từ 71 - 75.', 1, 1256375215490, 65, -1, 3, 1, 'Ngọc Phong Lâm', 1, '1220,290|2170,400|1210,1020|500,510|200,710|1210,1360|2310,1460|510,470|120,700|180,1030|950,1400|1760,1510|2280,1480|1210,1050|1990,540', '1220,290|2170,400|1210,1020|500,510|200,710|1210,1360|2310,1460|510,470|120,700|180,1030|950,1400|1760,1510|2280,1480|1210,1050|1990,540', 1015015000016, '0', 9, 0, 1600, 500, 1, 2, 2500),
	(17, 1, 50, 10, 1, 0, '|12|119|118|117|185|15|17|16|18|', 0, 0, 1, 1.00, 1, 1, 2000, 'Hòn đảo bé nhỏ như con thuyền đậu trên mặt hồ, là nơi đi dễ khó về. Thích hợp cho cấp độ từ 21 - 30.', 1, 1242826300937, 10, -1, 3, 1, 'Lê Dương Đảo', -1, '769,642|578,881|599,1346|532,1829|1252,1759|1764,1499|2117,1443|2370,976|2294,856|2434,320|2800,620|2110,1270|1690,1510|610,1590|530,810|1000,610|1500,460|2610,1040|1280,1720|2930,580|2600,1040|1660,1210|1980,1880|1280,1850|430,1650|510,810|980,400|1550,630|2090,550', '769,642|578,881|599,1346|532,1829|1252,1759|1764,1499|2117,1443|2370,976|2294,856|2434,320|2800,620|2110,1270|1690,1510|610,1590|530,810|1000,610|1500,460|2610,1040|1280,1720|2930,580|2600,1040|1660,1210|1980,1880|1280,1850|430,1650|510,810|980,400|1550,630|2090,550', 1015015000017, '0', 9, 0, 2265, 423, 1, 2, 3000),
